CREATE TABLE booking_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),guest_name text NOT NULL,address text NOT NULL,room_type text NOT NULL CHECK (room_type IN ('AC','Non-AC')),number_of_rooms integer NOT NULL CHECK (number_of_rooms > 0),total_guests integer NOT NULL CHECK (total_guests > 0),check_in_date date NOT NULL,check_out_date date NOT NULL CHECK (check_out_date > check_in_date),contact_number text NOT NULL,additional_requirements text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'New' CHECK (status IN ('New','Contacted','Confirmed','Cancelled')),created_at timestamptz NOT NULL DEFAULT NOW(),updated_at timestamptz NOT NULL DEFAULT NOW());